  4	/**
  5	 * A class representing shared characteristics of animals.
  6	 *
  7	 * @version 2022.03.02
  8	 */
  9	public abstract class Animal extends Organism implements Actor
 10	{
 11	
 12	    protected int age;
 13	    protected boolean isNocturnal;
 14	    protected int foodLevel;
 15	    protected Gender sex;
 16	
 17	    protected static final Random rand = Randomizer.getRandom();
 18	
 19	    // An animal is either male or female 
 20	    protected enum Gender {
 21	        MALE,
 22	        FEMALE
 23	    }
 24	    // An animal's chance of contracting a disease at birth
 25	    private double RANDOM_CONTRACTION_RATE = 0.002;
 26	
 27	
 28	    // Declaring abstract methods to obtain fields used by subclasses
 29	    // These methods have been declared in order to use common methods in the Animal class, reducing repeatability
 30	    protected abstract double BREEDING_AGE();
 31	    protected abstract int MAX_LITTER_SIZE();
 32	    protected abstract double BREEDING_PROBABILITY();
 33	    protected abstract int MAX_AGE();
 34	    protected abstract int MAX_FOOD_LEVEL();
 35	    protected abstract Set<Class> DIET();
 36	
 37	
 38	    /**
 39	     * Create a new animal at location in field.
 40	     *
 41	     * @param field The field currently occupied.
 42	     * @param location The location within the field.
 43	     * @param randomAge The animal's random starting age.
 44	     * @param sex The animal's gender. 
 45	     */
 46	    public Animal(Field field, Location location, boolean randomAge, Gender sex)
 47	    {
 48	        super(field, location);
 49	        this.sex = sex;
 50	        if(randomAge) {
 51	            this.age = rand.nextInt(MAX_AGE());
 52	            foodLevel = rand.nextInt(MAX_FOOD_LEVEL());
 53	        }
 54	        else {
 55	            this.age = 0;
 56	            foodLevel = MAX_FOOD_LEVEL();
 57	        }
 58	        randomlyContractDisease();
 59	    }
 60	
 61	    /**
 62	     * Make this animal act - that is: make it do
 63	     * whatever it wants/needs to do.
 64	     * @param newAnimals A list to receive newly born animals.
 65	     * @param environment The environment that the animal resides in.
 66	     */
 67	    public void act(List<Actor> newAnimals, Environment environment)
 68	    {
 69	        randomlyContractDisease();
 70	        incrementAge();
 71	        incrementHunger();
 72	        if(isAlive()) {
 73	            giveBirth(newAnimals, environment);
 74	            // Move towards a source of food if found.
 75	            Location newLocation = findFood();
 76	            if(newLocation == null) {
 77	                // No food found - try to move to a free location.
 78	                newLocation = getField().freeAdjacentLocation(getLocation());
 79	            }
 80	
 81	            // list of adjacent locations that contain an instance of Grass
 82	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
 83	
 84	            if(newLocation != null) {
 85	                // See if it was possible to move.
 86	                setLocation(newLocation);
 87	            }
 88	            else if (adjacentGrassSpots.size() > 0) {
 89	                // if there is grass adjacent to the animal, clear the current location
 90	                // and move to a random location that contained grass
 91	                getField().clear(getLocation());
 92	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
 93	            }
 94	            else {
 95	                // Overcrowding
 96	                setDead();
 97	            }
 98	
 99	            if(isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()){
100	                // every step, check if the Animal is diseased
101	                // if it is Diseased, and a random double is less than the lethality rate, the Animal dies
102	                setDead();
103	            }
104	
105	        }
106	    }
107	
108	    /**
109	     * Look for food adjacent to the current location.
110	     * Only the first food is eaten.
111	     * @return Where food was found, or null if it wasn't.
112	     */
113	    protected Location findFood()
114	    {
115	        Field field = getField();
116	        List<Location> adjacent = field.adjacentLocations(getLocation());
117	        for(Location loc : adjacent){
118	            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
119	                Organism organism = (Organism) field.getObjectAt(loc);
120	                if (organism.isDiseased() && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT && organism.getDisease().getPropagationRate() <= rand.nextDouble()){
121	                    // contracts the first contact disease it encounters amongst the adjacent animals
122	                    this.setDisease(organism.getDisease());
123	                    break;
124	                }
125	            }
126	        }
127	        Iterator<Location> it = adjacent.iterator();
128	        // only eats if it's not full (food level less than max)
129	        while(it.hasNext() && foodLevel <= MAX_FOOD_LEVEL()) {
130	            Location where = it.next();
131	            Object animal = field.getObjectAt(where);
132	            if(animal != null && DIET().contains(animal.getClass())) 
133	            {
134	                Organism food = (Organism) animal;
135	                if (food.isDiseased() &&  food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE && food.getDisease().getPropagationRate() <= rand.nextDouble()) 
136	                {
137	                    // contracts disease from food if it has a disease and that disease is foodborne
138	                    setDisease(food.getDisease());
139	                }
140	                if(food.isAlive()) 
141	                {
142	                    food.setDead();
143	                    int newFoodLevel = foodLevel + food.FOOD_VALUE();
144	
145	                    // caps the food level at the maximum
146	                    foodLevel = Math.min(newFoodLevel, MAX_FOOD_LEVEL());
147	
148	                    return where;
149	                }
150	                return where;
151	            }
152	        }
153	        return null;
154	    }
155	
156	    /**
157	     * Returns true if an animal contracts a disease at birth.
158	     * Returns false if otherwise. 
159	     */
160	    protected void randomlyContractDisease()
161	    {
162	        if(rand.nextDouble() <= RANDOM_CONTRACTION_RATE) {
163	            setDisease(new Disease());
164	        }
165	    }
166	
167	    /**
168	     * Check whether this animal is to give birth at this step.
169	     * New births will be made into free adjacent locations.
170	     * @param newAnimals A list to return newly born animals.
171	     * @param environment The environment that the animal resides in. 
172	     */
173	    protected abstract void giveBirth(List<Actor> newAnimals, Environment environment);
174	
175	    /**
176	     * Returns true if the animal is awake or not.
177	     */
178	    public boolean isAwake(Environment environment)
179	    {
180	        if(isNocturnal){
181	            return !environment.getTime().isDay();
182	        }
183	        return environment.getTime().isDay();
184	    }
185	
186	    /**
187	     * Generates a number representing the number of births,
188	     * if it can breed.
189	     * @return The number of births (may be zero)
190	     */
191	    protected int breed()
192	    {
193	        int births = 0;
194	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY()) {
195	            births = rand.nextInt(MAX_LITTER_SIZE()) + 1;
196	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
197	            if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL){
198	                this.setDisease(mate.getDisease());
199	            }
200	        }
201	        return births;
202	    }
203	
204	    /**
205	     * Returns true if the animal is able to breed.
206	     * Returns false if otherwise. 
207	     */
208	    protected boolean canBreed()
209	    {
210	        return (age >= BREEDING_AGE() && getPotentialMates().size() > 0);
211	    }
212	
213	    /**
214	     * Returns a list of potential mates. Mates have to be
215	     * of a opposite gender. 
216	     * @return List<Organism> A list of potential mates.
217	     */
218	    protected List<Organism> getPotentialMates()
219	    {
220	        List<Organism> potentialMates = new ArrayList<>();
221	        if(getField() != null){
222	            potentialMates = getField().adjacentLocations(getLocation()).stream()
223	                    .map(s -> getField().getObjectAt(s))
224	                    .filter(s -> s != null)
225	                    .filter(s -> s.getClass().equals(this.getClass()))
226	                    .filter(s -> this.sex != ((Animal) s).sex)
227	                    .map(s -> (Organism) s)
228	                    .collect(Collectors.toList());
229	            // stream counts the number of Animals of the same species, as well as opposite gender
230	        }
231	        return potentialMates;
232	    }
233	
234	
235	    /**
236	     * Increase the age. This could result in the animal's death.
237	     */
238	    protected void incrementAge()
239	    {
240	        this.age++;
241	        if(this.age > MAX_AGE()) {
242	            setDead();
243	        }
244	    }
245	
246	    /**
247	     * Make this animal more hungry. This could result in the animal's death.
248	     */
249	    protected void incrementHunger()
250	    {
251	        foodLevel--;
252	        if(foodLevel <= 0) {
253	            setDead();
254	        }
255	    }
256	
257	}

