 13	    private static int remainingSteps;
 14	
 15	    private static final Random rand = Randomizer.getRandom();
 16	
 17	    // Constants representing configuration information for the simulation.
 18	    // The default width for the grid.
 19	    private static final int DEFAULT_WIDTH = 240;
 20	    // The default depth of the grid.
 21	    private static final int DEFAULT_DEPTH = 160;
 22	
 23	    // A map of the creation probabilities for the organisms in the simulation
 24	    private static Map<Class<?>, Double> CREATION_PROBABILITIES = Map.ofEntries(
 25	            Map.entry(Coyote.class, 0.010),
 26	            Map.entry(Deer.class, 0.080),
 27	            Map.entry(Wolf.class, 0.010),
 28	            Map.entry(Eagle.class, 0.01),
