 38	
 39	
 40	    // List of actors in the field.
 41	    private List<Actor> actors;
 42	    // The current state of the field.
 43	    private Field field;
 44	    // The current step of the simulation.
 45	    private int step;
 46	    // A graphical view of the simulation.
