 62	     * @param MouseProbability Probability of Mouse being generated
 63	     */
 64	    public Simulator(double GrassProbability, double DeerProbability, double CoyoteProbability, double WolfProbability, double EagleProbability, double HunterProbability, double MouseProbability){
 65	        this(DEFAULT_WIDTH, DEFAULT_DEPTH);
 66	
 67	        CREATION_PROBABILITIES = Map.ofEntries(
 68	                Map.entry(Coyote.class, CoyoteProbability),
