 96	     */
 97	    public Simulator(int depth, int width)
 98	    {
 99	        if(width <= 0 || depth <= 0) {
100	            System.out.println("The dimensions must be greater than zero.");
101	            System.out.println("Using default values.");
102	            depth = DEFAULT_DEPTH;
103	            width = DEFAULT_WIDTH;
104	        }
105	
106	        actors = new ArrayList<>();
107	        field = new Field(depth, width);
108	        environment = new Environment(new Time(), new Weather());
