  7	/**
  8	 * A simple predator-prey simulator, based on a rectangular field
  9	 * containing different organisms.
 10	 *
 11	 * @version 2022.03.02
 12	 */
 13	public class Simulator
 14	{
 15	    private static final Random rand = Randomizer.getRandom();
 16	
 17	    private boolean playingSimulation;
 18	    private int remainingSteps;
 19	
 20	    // List of actors in the field.
 21	    private final List<Actor> actors;
 22	    // The current state of the field.
 23	    private final Field field;
 24	    // The current step of the simulation.
 25	    private int step;
 26	    // A graphical view of the simulation.
 27	    private final SimulatorView view;
 28	    // Environment in the simulation.
 29	    private final Environment environment;
 30	    // Configuration and actor creation rules for the simulation.
 31	    private final SimulationConfig config;
 32	    private final ActorFactory actorFactory;
 33	
 34	    /**
 35	     * A simulator constructor to set the creation probability of each actor.
 36	     * This constructor can be used to test different combinations of probabilities.
 37	     */
 38	    public Simulator(double grassProbability,
 39	            double deerProbability,
 40	            double coyoteProbability,
 41	            double wolfProbability,
 42	            double eagleProbability,
 43	            double hunterProbability,
 44	            double mouseProbability)
 45	    {
 46	        this(
 47	                SimulationConfig.withCreationProbabilities(
 48	                        grassProbability,
 49	                        deerProbability,
 50	                        coyoteProbability,
 51	                        wolfProbability,
 52	                        eagleProbability,
 53	                        hunterProbability,
 54	                        mouseProbability
 55	                ),
 56	                SimulationConfig.DEFAULT_DEPTH,
 57	                SimulationConfig.DEFAULT_WIDTH
 58	        );
 59	    }
 60	
 61	    /**
 62	     * Construct a simulation field with default size.
 63	     */
 64	    public Simulator()
 65	    {
 66	        this(SimulationConfig.defaultConfig(), SimulationConfig.DEFAULT_DEPTH, SimulationConfig.DEFAULT_WIDTH);
 67	    }
 68	
 69	    /**
 70	     * Create a simulation field with the given size.
 71	     * @param depth Depth of the field. Must be greater than zero.
 72	     * @param width Width of the field. Must be greater than zero.
 73	     */
 74	    public Simulator(int depth, int width)
 75	    {
 76	        this(SimulationConfig.defaultConfig(), depth, width);
 77	    }
 78	
 79	    private Simulator(SimulationConfig config, int depth, int width)
 80	    {
 81	        if(width <= 0 || depth <= 0) {
 82	            System.out.println("The dimensions must be greater than zero.");
 83	            System.out.println("Using default values.");
 84	            depth = SimulationConfig.DEFAULT_DEPTH;
 85	            width = SimulationConfig.DEFAULT_WIDTH;
 86	        }
 87	
 88	        this.config = config;
 89	        this.actors = new ArrayList<>();
 90	        this.field = new Field(depth, width);
 91	        this.environment = new Environment(new Time(), new Weather());
 92	        this.actorFactory = new ActorFactory(config);
 93	        this.view = createView(depth, width);
 94	
 95	        reset();
 96	    }
 97	
 98	    /**
 99	     * Run the simulation from its current state for a reasonably long period.
100	     */
101	    public void runLongSimulation()
102	    {
103	        remainingSteps += SimulationConfig.LONG_SIMULATION_STEPS;
104	        simulate(remainingSteps);
105	    }
106	
107	    /**
108	     * Run the simulation from its current state for the given number of steps.
109	     * Stop before the given number of steps if it ceases to be viable.
110	     * @param numSteps The number of steps to run for.
111	     */
112	    public void simulate(int numSteps)
113	    {
114	        playingSimulation = true;
115	        remainingSteps = numSteps;
116	
117	        int completedSteps = 0;
118	        while(playingSimulation){
119	            for(int currentStep = 0; currentStep < numSteps && playingSimulation && view.isViable(field); currentStep++) {
120	                simulateOneStep();
121	                completedSteps++;
122	//                delay(60);   // uncomment this to run more slowly
123	            }
124	            if(!view.isViable(field)){
125	                updateBestSimulationResult(completedSteps);
126	                playingSimulation = false;
127	            }
128	        }
129	
130	        remainingSteps = Math.max(0, numSteps - completedSteps);
131	    }
132	
133	    /**
134	     * Run the simulation from its current state for a single step.
135	     * Iterate over the whole field updating the state of each organism.
136	     */
137	    public void simulateOneStep()
138	    {
139	        if(!playingSimulation) {
140	            return;
141	        }
142	
143	        step++;
144	        environment.advance(step);
145	
146	        List<Actor> newActors = new ArrayList<>();
147	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
148	            Actor actor = it.next();
149	            processActor(actor, newActors);
150	            maybeGrowPlant(actor);
151	
152	            if(!actor.isAlive()) {
153	                it.remove();
154	            }
155	        }
156	
157	        actors.addAll(newActors);
158	        actors.addAll(actorFactory.createGrassPatches(field, environment));
159	        showStatus();
160	    }
161	
162	    /**
163	     * Reset the simulation to a starting position.
164	     */
165	    public void reset()
166	    {
167	        playingSimulation = false;
168	        remainingSteps = 0;
169	        step = 0;
170	        environment.reset();
171	
172	        actors.clear();
173	        actors.addAll(actorFactory.populate(field));
174	
175	        showStatus();
176	    }
177	
178	    /**
179	     * Pause for a given time.
180	     * @param millisec  The time to pause for, in milliseconds
181	     */
182	    private void delay(int millisec)
183	    {
184	        try {
185	            Thread.sleep(millisec);
186	        }
187	        catch (InterruptedException ie) {
188	            // wake up
189	        }
190	    }
191	
192	    private SimulatorView createView(int depth, int width)
193	    {
194	        SimulatorView simulatorView = new SimulatorView(depth, width);
195	        for(Class<?> cls : SimulationInfo.DEFAULT_COLOR_MAP.keySet()) {
196	            simulatorView.setColor(cls, SimulationInfo.DEFAULT_COLOR_MAP.get(cls));
197	        }
198	
199	        simulatorView.addLongButtonListener(longButtonListener);
200	        simulatorView.addOneStepButtonListener(startButtonListener);
201	        simulatorView.addStopButtonListener(stopButtonListener);
202	        simulatorView.addResetButtonListener(resetButtonListener);
203	        return simulatorView;
204	    }
205	
206	    private void processActor(Actor actor, List<Actor> newActors)
207	    {
208	        if(actor instanceof Animal animal) {
209	            if(!animal.isAwake(environment)) {
210	                return;
211	            }
212	            if(animal.isDiseased() && animal.getDisease().getPropagationRate() <= rand.nextDouble()) {
213	                animal.setDead();
214	            }
215	        }
216	
217	        if(actor.isAlive()) {
218	            actor.act(newActors, environment);
219	        }
220	    }
221	
222	    private void maybeGrowPlant(Actor actor)
223	    {
224	        if(actor instanceof Plant plant && step % plant.getStepsPerStage() == 0) {
225	            plant.incrementGrowth();
226	        }
227	    }
228	
229	    private void showStatus()
230	    {
231	        view.showStatus(
232	                step,
233	                environment.getWeather().getCurrentWeather().toString(),
234	                environment.getTime().getCurrentTimeString(),
235	                field
236	        );
237	    }
238	
239	    private void updateBestSimulationResult(int completedSteps)
240	    {
241	        if(completedSteps > SimulationInfo.HIGHEST_STEPS) {
242	            SimulationInfo.HIGHEST_STEPS = completedSteps;
243	            SimulationInfo.HIGHEST_STEP_PROBS = config.getCreationProbabilities();
244	        }
245	    }
246	
247	    /**
248	     * Whenever the start button is pressed, the simulateOneStep() method is called.
249	     */
250	    private final ActionListener startButtonListener = e -> {
251	        if(playingSimulation) {
252	            System.out.println("Stop the simulation first");
253	        }
254	        else {
255	            playingSimulation = true;
256	            simulateOneStep();
257	            playingSimulation = false;
258	        }
259	    };
