  4	/**
  5	 * A class representing shared characteristics of animals.
  6	 *
  7	 * @version 2022.03.02
  8	 */
  9	public abstract class Animal extends Organism implements Actor
 10	{
 11	    private static final double RANDOM_CONTRACTION_RATE = 0.002;
 12	
 13	    protected int age;
 14	    protected boolean isNocturnal;
 15	    protected int foodLevel;
 16	    protected Gender sex;
 17	
 18	    protected static final Random rand = Randomizer.getRandom();
 19	
 20	    // An animal is either male or female 
 21	    protected enum Gender {
 22	        MALE,
 23	        FEMALE
 24	    }
 25	
 26	
 27	    // Declaring abstract methods to obtain fields used by subclasses
 28	    // These methods have been declared in order to use common methods in the Animal class, reducing repeatability
 29	    protected abstract int getBreedingAge();
 30	    protected abstract int getMaxLitterSize();
 31	    protected abstract double getBreedingProbability();
 32	    protected abstract int getMaxAge();
 33	    protected abstract int getMaxFoodLevel();
 34	    protected abstract Set<Class<? extends Organism>> getDiet();
 35	    protected abstract Animal createYoung(Field field, Location location, Gender sex);
 36	
 37	
 38	    /**
 39	     * Create a new animal at location in field.
 40	     *
 41	     * @param field The field currently occupied.
 42	     * @param location The location within the field.
 43	     * @param randomAge The animal's random starting age.
 44	     * @param sex The animal's gender. 
 45	     */
 46	    public Animal(Field field, Location location, boolean randomAge, Gender sex)
 47	    {
 48	        super(field, location);
 49	        this.sex = sex;
 50	        if(randomAge) {
 51	            this.age = rand.nextInt(getMaxAge());
 52	            foodLevel = rand.nextInt(getMaxFoodLevel());
 53	        }
 54	        else {
 55	            this.age = 0;
 56	            foodLevel = getMaxFoodLevel();
 57	        }
 58	        randomlyContractDisease();
 59	    }
 60	
 61	    /**
 62	     * Make this animal act - that is: make it do
 63	     * whatever it wants/needs to do.
 64	     * @param newAnimals A list to receive newly born animals.
 65	     * @param environment The environment that the animal resides in.
 66	     */
 67	    public void act(List<Actor> newAnimals, Environment environment)
 68	    {
 69	        randomlyContractDisease();
 70	        incrementAge();
 71	        incrementHunger();
 72	        if(isAlive()) {
 73	            giveBirth(newAnimals, environment);
 74	            // Move towards a source of food if found.
 75	            Location newLocation = findFood(environment);
 76	            if(newLocation == null) {
 77	                // No food found - try to move to a free location.
 78	                newLocation = getField().freeAdjacentLocation(getLocation());
 79	            }
 80	
 81	            // list of adjacent locations that contain an instance of Grass
 82	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
 83	
 84	            if(newLocation != null) {
 85	                // See if it was possible to move.
 86	                setLocation(newLocation);
 87	            }
 88	            else if (adjacentGrassSpots.size() > 0) {
 89	                // if there is grass adjacent to the animal, clear the current location
 90	                // and move to a random location that contained grass
 91	                getField().clear(getLocation());
 92	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
 93	            }
 94	            else {
 95	                // Overcrowding
 96	                setDead();
 97	            }
 98	
 99	            if(isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()){
100	                // every step, check if the Animal is diseased
101	                // if it is Diseased, and a random double is less than the lethality rate, the Animal dies
102	                setDead();
103	            }
104	
105	        }
106	    }
107	
108	    /**
109	     * Look for food adjacent to the current location.
110	     * Only the first food is eaten.
111	     * @return Where food was found, or null if it wasn't.
112	     */
113	    protected Location findFood(Environment environment)
114	    {
115	        return findFood();
116	    }
117	
118	    /**
119	     * Look for food adjacent to the current location.
120	     * Only the first food is eaten.
121	     * @return Where food was found, or null if it wasn't.
122	     */
123	    protected Location findFood()
124	    {
125	        Field field = getField();
126	        List<Location> adjacent = field.adjacentLocations(getLocation());
127	        for(Location loc : adjacent){
128	            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
129	                Organism organism = (Organism) field.getObjectAt(loc);
130	                if (organism.isDiseased() && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT && organism.getDisease().getPropagationRate() <= rand.nextDouble()){
131	                    // contracts the first contact disease it encounters amongst the adjacent animals
132	                    this.setDisease(organism.getDisease());
133	                    break;
134	                }
135	            }
136	        }
137	        Iterator<Location> it = adjacent.iterator();
138	        // only eats if it's not full (food level less than max)
139	        while(it.hasNext() && foodLevel <= getMaxFoodLevel()) {
140	            Location where = it.next();
141	            Object animal = field.getObjectAt(where);
142	            if(animal != null && getDiet().contains(animal.getClass()))
143	            {
144	                Organism food = (Organism) animal;
145	                if (food.isDiseased() &&  food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE && food.getDisease().getPropagationRate() <= rand.nextDouble()) 
146	                {
147	                    // contracts disease from food if it has a disease and that disease is foodborne
148	                    setDisease(food.getDisease());
149	                }
150	                if(food.isAlive()) 
151	                {
152	                    food.setDead();
153	                    int newFoodLevel = foodLevel + food.getFoodValue();
154	
155	                    // caps the food level at the maximum
156	                    foodLevel = Math.min(newFoodLevel, getMaxFoodLevel());
157	
158	                    return where;
159	                }
160	                return where;
161	            }
162	        }
163	        return null;
164	    }
165	
166	    /**
167	     * Returns true if an animal contracts a disease at birth.
168	     * Returns false if otherwise. 
169	     */
170	    protected void randomlyContractDisease()
171	    {
172	        if(rand.nextDouble() <= RANDOM_CONTRACTION_RATE) {
173	            setDisease(new Disease());
174	        }
175	    }
176	
177	    /**
178	     * Check whether this animal is to give birth at this step.
179	     * New births will be made into free adjacent locations.
180	     * @param newAnimals A list to return newly born animals.
181	     * @param environment The environment that the animal resides in. 
182	     */
183	    protected void giveBirth(List<Actor> newAnimals, Environment environment)
184	    {
185	        Field field = getField();
186	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
187	        int births = breed();
188	        for(int b = 0; b < births && !free.isEmpty(); b++) {
189	            Location loc = free.remove(0);
190	            Gender sex = Randomizer.getRandomSex();
191	            newAnimals.add(createYoung(field, loc, sex));
192	        }
193	    }
194	
195	    /**
196	     * Returns true if the animal is awake or not.
197	     */
198	    public boolean isAwake(Environment environment)
199	    {
200	        if(isNocturnal){
201	            return !environment.getTime().isDay();
202	        }
203	        return environment.getTime().isDay();
204	    }
205	
206	    /**
207	     * Generates a number representing the number of births,
208	     * if it can breed.
209	     * @return The number of births (may be zero)
210	     */
211	    protected int breed()
212	    {
213	        int births = 0;
214	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
215	            births = rand.nextInt(getMaxLitterSize()) + 1;
216	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
217	            if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL){
218	                this.setDisease(mate.getDisease());
219	            }
220	        }
221	        return births;
222	    }
223	
224	    /**
225	     * Returns true if the animal is able to breed.
226	     * Returns false if otherwise. 
227	     */
228	    protected boolean canBreed()
229	    {
230	        return age >= getBreedingAge() && !getPotentialMates().isEmpty();
231	    }
232	
233	    /**
234	     * Returns a list of potential mates. Mates have to be
235	     * of a opposite gender. 
236	     * @return List<Organism> A list of potential mates.
237	     */
238	    protected List<Organism> getPotentialMates()
239	    {
240	        List<Organism> potentialMates = new ArrayList<>();
241	        if(getField() != null){
242	            potentialMates = getField().adjacentLocations(getLocation()).stream()
243	                    .map(s -> getField().getObjectAt(s))
244	                    .filter(s -> s != null)
245	                    .filter(s -> s.getClass().equals(this.getClass()))
246	                    .filter(s -> this.sex != ((Animal) s).sex)
247	                    .map(s -> (Organism) s)
248	                    .collect(Collectors.toList());
249	            // stream counts the number of Animals of the same species, as well as opposite gender
250	        }
251	        return potentialMates;
252	    }
253	
254	
255	    /**
256	     * Increase the age. This could result in the animal's death.
257	     */
258	    protected void incrementAge()
259	    {
260	        this.age++;
261	        if(this.age > getMaxAge()) {
262	            setDead();
263	        }
264	    }
265	
266	    /**
267	     * Make this animal more hungry. This could result in the animal's death.
268	     */
269	    protected void incrementHunger()
270	    {
271	        foodLevel--;
272	        if(foodLevel <= 0) {
273	            setDead();
274	        }
275	    }
276	
277	}

  1	import java.util.ArrayList;
  2	import java.util.List;
  3	import java.util.Random;
  4	
  5	/**
  6	 * Creates actors and populates fields according to a simulation configuration.
  7	 */
  8	public class ActorFactory
  9	{
 10	    private static final Random rand = Randomizer.getRandom();
 11	    private static final List<Class<?>> CREATION_ORDER = List.of(
 12	            Grass.class,
 13	            Deer.class,
 14	            Coyote.class,
 15	            Wolf.class,
 16	            Eagle.class,
 17	            Mouse.class,
 18	            Hunter.class
 19	    );
 20	
 21	    private final SimulationConfig config;
 22	
 23	    public ActorFactory(SimulationConfig config)
 24	    {
 25	        this.config = config;
 26	    }
 27	
 28	    public List<Actor> populate(Field field)
 29	    {
 30	        List<Actor> actors = new ArrayList<>();
 31	        int hunterCount = 0;
 32	
 33	        field.clear();
 34	        for(int row = 0; row < field.getDepth(); row++) {
 35	            for(int col = 0; col < field.getWidth(); col++) {
 36	                Location location = new Location(row, col);
 37	                Actor actor = maybeCreateActor(field, location, hunterCount);
 38	                if(actor != null) {
 39	                    actors.add(actor);
 40	                    if(actor instanceof Hunter) {
 41	                        hunterCount++;
 42	                    }
 43	                }
 44	            }
 45	        }
 46	
 47	        return actors;
 48	    }
 49	
 50	    public List<Actor> createGrassPatches(Field field, Environment environment)
 51	    {
 52	        if(environment.getWeather().getCurrentWeather() != WeatherType.RAINING) {
 53	            return List.of();
 54	        }
 55	
 56	        double creationRate = config.getCreationProbability(Grass.class);
 57	        List<Actor> grassActors = new ArrayList<>();
 58	        for(Location location : field.getRandomFreePatches(creationRate)) {
 59	            if(rand.nextDouble() <= creationRate) {
 60	                grassActors.add(new Grass(field, location));
 61	            }
 62	        }
 63	
 64	        return grassActors;
 65	    }
 66	
 67	    private Actor maybeCreateActor(Field field, Location location, int hunterCount)
 68	    {
 69	        for(Class<?> actorClass : CREATION_ORDER) {
 70	            if(actorClass == Hunter.class && hunterCount >= config.getHunterLimit()) {
 71	                continue;
 72	            }
 73	
 74	            if(rand.nextDouble() <= config.getCreationProbability(actorClass)) {
 75	                return createActor(actorClass, field, location);
 76	            }
 77	        }
 78	
 79	        return null;
 80	    }
 81	
 82	    private Actor createActor(Class<?> actorClass, Field field, Location location)
 83	    {
 84	        if(actorClass == Grass.class) {
 85	            return new Grass(field, location);
 86	        }
 87	        if(actorClass == Hunter.class) {
 88	            return new Hunter(field, location);
 89	        }
 90	
 91	        Animal.Gender sex = Randomizer.getRandomSex();
 92	        if(actorClass == Deer.class) {
 93	            return new Deer(true, field, location, sex);
 94	        }
 95	        if(actorClass == Coyote.class) {
 96	            return new Coyote(true, field, location, sex);
 97	        }
 98	        if(actorClass == Wolf.class) {
 99	            return new Wolf(true, field, location, sex);
100	        }
101	        if(actorClass == Eagle.class) {
102	            return new Eagle(true, field, location, sex);
103	        }
104	        if(actorClass == Mouse.class) {
105	            return new Mouse(true, field, location, sex);
106	        }
107	
108	        throw new IllegalArgumentException("Unsupported actor type: " + actorClass.getName());
109	    }
110	}

