11	    // A hunter hunts every species. 
12	    private static final Set<Class<? extends Organism>> DIET = new HashSet<>(Arrays.asList(
13	            Deer.class,
14	            Mouse.class,
15	            Wolf.class,
16	            Coyote.class,
17	            Eagle.class
18	    ));
