20	
21	    /**
22	     * Creates a new hunter.
23	     * @param field The field currently occupied.
24	     * @param location  The location within the field.
25	     */
26	    public Hunter(Field field, Location location)
27	    {
28	        super(field, location);
29	    }
30	
31	    @Override
32	    protected int getFoodValue()
33	    {
34	        return 0;
35	    }
36	
37	    /**
38	     * Makes the hunter hunt for nearby animals. 
39	     * @param environment The environment that the hunter resides in. 
40	     * @param newActors A list to receive new actors. 
41	     */
42	    public void act(List<Actor> newActors, Environment environment)
43	    {
44	        if(isAlive()) {
45	            Location newLocation = findPrey();
46	            if(newLocation == null) {
47	                // No animals found - try to move to a free location.
48	                newLocation = getField().freeAdjacentLocation(getLocation());
49	            }
50	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
51	
52	            // See if it was possible to move.
53	            if(newLocation != null) {
54	                setLocation(newLocation);
55	            }
56	            else if (adjacentGrassSpots.size() > 0) {
57	                getField().clear(getLocation());
58	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
59	            }
60	
61	        }
62	    }
63	
64	    /**
65	     * Look for animals adjacent to the current location.
66	     * Only the first live animal is killed.
67	     * @return Location Where an animal was found, or null if it wasn't.
68	     */
69	    private Location findPrey()
70	    {
71	        Field field = getField();
72	        Location currentLocation = getLocation();
73	        List<Location> adjacent = field.adjacentLocations(currentLocation);
74	        Iterator<Location> it = adjacent.iterator();
75	        while(it.hasNext()) {
76	            Location where = it.next();
77	            Object animal = field.getObjectAt(where);
78	            if(animal != null && DIET.contains(animal.getClass())) {
79	                Organism food = (Organism) animal;
80	                if(food.isAlive()) {
81	                    food.setDead();
82	                    return where;
83	                }
84	                return where;
85	            }
86	        }
87	        return null;
88	    }
89	}

