  3	/**
  4	 * This class models grass.
  5	 * Grass can germinate,grow and get eaten by animals.
  6	 * @version 2022.03.02
  7	 */
  8	public class Grass extends Plant
  9	{
 10	    private static final int MAX_GROWTH_STAGES = 3;
 11	    private static final int DEFAULT_STEPS_PER_STAGE = 2;
 12	    private static final double BASE_GERMINATION_RATE = 0.1;
 13	    private static final double SUNNY_GERMINATION_RATE = 0.15;
 14	
 15	    private int foodValue;
 16	
 17	    /**
 18	     * Returns the food value of the grass.
 19	     * @return int The food value of the grass.
 20	     */
 21	    protected int getFoodValue()
 22	    {
 23	        return foodValue;
 24	    }
 25	
 26	    /**
 27	     * Creates grass with a random stage of growth.
 28	     * However, the maximum number of stages is fixed at 3,
 29	     * and the growth rate is fixed at 2 steps per stage.
 30	     *
 31	     * @param field The field currently occupied.
 32	     * @param location The location within the field.
 33	     */
 34	    public Grass(Field field, Location location)
 35	    {
 36	        super(field, location);
 37	
 38	        numberOfStages = MAX_GROWTH_STAGES;
 39	        stepsPerStage = DEFAULT_STEPS_PER_STAGE;
 40	        stageOfGrowth = rand.nextInt(numberOfStages);
 41	        foodValue = stageOfGrowth;
 42	
 43	    }
 44	
 45	
 46	    /**
 47	     * Make the grass act.
 48	     * The germination rate of grass is affected by weather.
 49	     * @param newGrass To store the newly germinated grass.
 50	     * @param environment The environment that the grass resides in.
 51	     */
 52	    public void act(List<Actor> newGrass, Environment environment)
 53	    {
 54	        if(isAlive()
 55	                && environment.getTime().isDay()
 56	                && rand.nextDouble() <= getGerminationRate(environment)
 57	                && environment.getWeather().getCurrentWeather() != WeatherType.CLOUDY) {
 58	            germinate(newGrass);
 59	        }
 60	    }
 61	
 62	    /**
 63	     * Check whether this grass is to germinate at this step.
 64	     * New grass will be made into free adjacent locations.
 65	     * @param newGrass A list to return newly made grass.
 66	     */
 67	    protected void germinate(List<Actor> newGrass)
 68	    {
 69	        // New grass are made into adjacent locations.
 70	        // Get a list of adjacent free locations.
 71	        Field field = getField();
 72	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
 73	        for(int b = 0; b < free.size(); b++) {
 74	            Location loc = free.remove(0);
 75	            Grass young = new Grass(field, loc);
 76	            newGrass.add(young);
 77	        }
 78	    }
 79	
 80	    /**
 81	     * Increment the stage of growth of grass
 82	     * Incrementing the growth also increases the food level by 1
 83	     * @return true If the grass grows.
 84	     * @return false If the grass doesn't grow.
 85	     */
 86	    public boolean incrementGrowth()
 87	    {
 88	        if(super.incrementGrowth()) {
 89	            foodValue++;
 90	            return true;
 91	        }
 92	        return false;
 93	    }
 94	
 95	    private double getGerminationRate(Environment environment)
 96	    {
 97	        if(environment.getWeather().getCurrentWeather() == WeatherType.SUNNY) {
 98	            return SUNNY_GERMINATION_RATE;
 99	        }
100	        return BASE_GERMINATION_RATE;
101	    }
102	
103	}

